1: // DOCUMENTS: panel controller — wires stage selection, trace controls, the
2: // interactive mini-browser, node selection, and the crowd sim to the engine.
3: // All behavior is attached with addEventListener only (no inline handlers —
4: // AGENTS.md CSP rule; the static server enforces it), and DOM updates are
5: // delegated to render.js.
6: import { createEngine } from '../sim/engine.js';
7: import { TICK_MS } from './model.js';
8: import { COMPONENT_SOURCE } from './inspector-source.js';
9: import { $, els, addToJourney, relabelJourneyRun, render, renderInspector } from './render.js';
10: import { renderStageTopology, onStageRendered } from './render-stage.js';
11: import { ensureStage6Dom } from './stage6-registry.js';
12: import { initFilesystemEditor } from './fs-editor.js';
13: import { initViewport } from './viewport.js';
14: import { initTeachingDrawer, renderTeaching } from './teaching-drawer.js';
