16: // Stage-6 topology DOM (DNS/Router cards, wire columns, inspector tabs) is
17: // injected before the wiring loops below so every getElementById resolves.
18: ensureStage6Dom();
19: 
20: let currentStage = 1;
21: let engine = null;
22: let timer = null;
23: let selectedComponent = 'browser';
24: let currentSnapshot = null;
25: // The browser currently expanded into #node-browser (mini-IP on Ring 3);
26: // every other browser renders as a compact clickable node in its slot.
27: let activeBrowserAddress = '10.2';
28: // Total hops per stage's trace shape; trace.js, trace-stage6.js and
29: // model.js's labels agree (stage 6's hosted shape: ask + answer + the
30: // stage-5 wire chain = 9).
31: const TOTAL_HOPS = { 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 9 };
32: 
33: const totalHopsFor = (stage) => TOTAL_HOPS[stage] ?? TOTAL_HOPS[1];
34: 
35: // CHECKS: the live final hop reads from the trace itself — stage 6's shape
36: // is (nx ? 2 : cdn ? (edgeStatus === 'HIT' ? 6 : 9) : host ? 9 : 8)
37: // (mirroring trace-stage6.js), so a host-less trace stops at its normal
38: // stage-5 count, an NX answer stops at the answer hop, and a CDN GET stops
39: // at 6 only after the answer proved an edge HIT; other stages use
40: // TOTAL_HOPS.
41: const traceFinalHop = (snapshot, stage) => {
42:   if (snapshot.stage === 6 && snapshot.trace) {
43:     if (snapshot.trace.nx) return 2;
44:     if (snapshot.trace.cdn) return snapshot.trace.edgeStatus === 'HIT' ? 6 : 9;
45:     return snapshot.trace.host ? 9 : 8;
46:   }
47:   return totalHopsFor(stage);
48: };
