50: function createEngineFromControls() {
51:   return createEngine({
52:     seed: 42,
53:     users: Number($('users-slider').value),
54:     serviceRate: 4,
55:     arrivalProb: 0.5,
56:     stage: currentStage,
57:   });
58: }
