68: function selectComponent(component) {
69:   if (!COMPONENT_SOURCE[component]) return;
70:   selectedComponent = component;
71:   renderInspector(selectedComponent, currentSnapshot, activeBrowserAddress);
72:   for (const tab of document.querySelectorAll('.comp-tab')) {
73:     tab.classList.toggle('active-tab', tab.dataset.select === component);
74:   }
75:   for (const card of document.querySelectorAll('.node-card')) {
76:     card.classList.toggle('selected-node', card.dataset.component === component);
77:   }
78: }
