80: function start() {
81:   timer = setInterval(() => {
82:     const snapshot = engine.step();
83:     if (snapshot.lastFrame) {
84:       // Each tick's frame is its own journey run: newer ticks float above
85:       // older ones in #journey-log (render.js sorts by run key).
86:       addToJourney(`tick ${snapshot.tick}`, snapshot.lastFrame, { run: nextJourneyRun() });
87:     }
88:     updateView(snapshot);
89:   }, TICK_MS);
90:   $('start-button').textContent = 'Pause';
91: }
92: 
93: function pause() {
94:   clearInterval(timer);
95:   timer = null;
96:   $('start-button').textContent = 'Start';
97: }
