99: function switchStage(stage) {
100:   if (timer) pause();
101:   currentStage = stage;
102:   renderStageTopology(currentStage);
103:   engine = createEngineFromControls();
104:   syncUrlState();
105:   renderTeaching(currentStage);
106:   updateView(engine.snapshot());
107: }
108: 
109: // CHECKS: deep-linked state reads exactly once at load — ?stage=N selects a
110: // live stage 1-6 and ?users=U clamps into the slider's 1-50 range; anything
111: // unknown, out of range, or non-numeric falls back to the fresh-load
112: // defaults (Stage 1, five users) without a console error. Named
113: // counter-example (pinned in e2e/panel.spec.js): ?stage=9 renders Stage 1 —
114: // out-of-range values must not crash or half-select a pill.
115: function readDeepLink() {
116:   const params = new URLSearchParams(window.location.search);
117:   const stage = Number.parseInt(params.get('stage') ?? '', 10);
118:   const users = Number.parseFloat(params.get('users') ?? '');
119:   return {
120:     stage: stage >= 1 && stage <= 6 ? stage : 1,
121:     users: Number.isFinite(users) ? Math.min(50, Math.max(1, Math.round(users))) : 5,
122:   };
123: }
124: 
125: // CHECKS: stage-pill clicks and user-slider commits rewrite the URL in place
126: // via history.replaceState — the shareable state tracks the panel without
127: // pushing history entries (no history spam). Existing params are preserved.
128: function syncUrlState() {
129:   const params = new URLSearchParams(window.location.search);
130:   params.set('stage', String(currentStage));
131:   params.set('users', $('users-slider').value);
132:   window.history.replaceState(null, '', `${window.location.pathname}?${params}`);
133: }
134: 
135: $('start-button').addEventListener('click', () => {
136:   if (timer) pause();
137:   else start();
138: });
139: 
140: $('step-button').addEventListener('click', () => {
141:   if (timer) pause();
142:   const snapshot = engine.step();
143:   if (snapshot.lastFrame) {
144:     addToJourney(`tick ${snapshot.tick}`, snapshot.lastFrame, { run: nextJourneyRun() });
145:   }
146:   updateView(snapshot);
147: });
