149: $('users-slider').addEventListener('input', () => {
150:   const users = Number($('users-slider').value);
151:   engine.setUsers(users);
152:   // A shrunken crowd drops its highest mini-IP slots; if the expanded browser
153:   // no longer exists, fall back to the learner's own browser.
154:   const host = Number(String(activeBrowserAddress).split('.')[1]);
155:   if (host > users + 1) activeBrowserAddress = '10.2';
156:   viewport.syncLayout(); // browser slots + crowd satellites re-space on Ring 3
157:   syncUrlState(); // user-count changes stay shareable
158:   updateView(engine.snapshot());
159: });
