209: $('btn-url-go').addEventListener('click', () => {
210:   if (timer) pause();
211:   for (let i = 0; i < totalHopsFor(currentStage) + 1; i += 1) {
212:     const snapshot = stepOneHop();
213:     if (snapshot.trace.hop === traceFinalHop(snapshot, currentStage)) break;
214:   }
215: });
