221: // Clicking a compact browser on Ring 3 expands it into #node-browser at its
222: // orbital position and collapses the previously expanded browser (10.2
223: // included) into a compact node in its own slot.
224: document.getElementById('browser-ring-nodes').addEventListener('click', (e) => {
225:   const chip = e.target.closest('.browser-compact');
226:   if (!chip) return;
227:   activeBrowserAddress = chip.dataset.address;
228:   viewport.syncLayout(); // moves #node-browser + wire lane to the new slot
229:   selectComponent('browser');
230:   updateView(engine.snapshot());
231: });
232: 
233: // Clicking a node card selects it in the bottom inspector (clicks on the
234: // mini-browser's own inputs/select/buttons stay with those controls).
235: document.querySelectorAll('.node-card').forEach((card) => {
236:   card.addEventListener('click', (e) => {
237:     if (e.target.closest('input, select, button')) return;
238:     selectComponent(card.dataset.component);
239:   });
240: });
241: 
242: document.querySelectorAll('.comp-tab').forEach((tab) => {
243:   tab.addEventListener('click', () => selectComponent(tab.dataset.select));
244: });
245: 
246: // CHECKS: the legend drawer toggles closed by default and reveals the app's
247: // own glossary (tick clock, cache stats trio, Ring 3 site chips, wire-lane
248: // direction labels); aria-expanded tracks visibility for assistive tech.
249: $('legend-toggle').addEventListener('click', () => {
250:   const panel = document.getElementById('legend-panel');
251:   const open = panel.hidden;
252:   panel.hidden = !open;
253:   $('legend-toggle').setAttribute('aria-expanded', String(open));
254: });
255: 
256: // CHECKS: the teaching drawer lives in js/panel/teaching-drawer.js; panel.js
257: // hands it the current stage at boot and on every switch (see also the
258: // legend drawer above for the toggle pattern).
259: initTeachingDrawer();
260: 
261: // CHECKS: the filesystem lists are the sim's own view — the editor module
262: // (fs-editor.js) renders both cards' rows from snapshot.servers[i].files and
263: // wires its pencil/input/buttons by delegation on those shells; a commit
264: // writes engine.setWebFile and updateView re-renders from the fresh
265: // snapshot, so the row, the next served record and the browser viewport all
266: // read the new bytes (brief negative case). panel.js passes only the engine
267: // accessor and the re-render callback; no inline handlers anywhere.
268: initFilesystemEditor({
269:   getEngine: () => engine,
270:   rerender: (snapshot) => updateView(snapshot),
271: });
272: 
273: // Boot: Stage 1 is active by default so existing Stage 1 tests run unchanged,
274: // except where the URL deep-links a live stage and user count (?stage=N&
275: // users=U) — those restore shared states on load. The viewport fits the
276: // active stage bounds at init and on every stage switch (via the
277: // onStageRendered hook), so every node card is on-screen from load.
278: const deepLink = readDeepLink();
279: currentStage = deepLink.stage;
280: $('users-slider').value = String(deepLink.users);
281: engine = createEngineFromControls();
282: renderStageTopology(currentStage);
283: const viewport = initViewport({
284:   viewportEl: $('orrery-viewport'),
285:   worldEl: $('orrery-world'),
286:   svgEl: $('orrery-svg'),
287:   getStage: () => currentStage,
288:   getUsers: () => Number($('users-slider').value),
289:   getActiveBrowser: () => activeBrowserAddress,
290: });
291: onStageRendered(() => viewport.syncLayout());
292: selectComponent('browser');
293: renderTeaching(currentStage);
294: updateView(engine.snapshot());

