3: // balancer backend counters, and inspector panes). Stage topology and hop
4: // highlights live in render-stage.js; event wiring in panel.js.
5: import { describeSnapshot, orderJourneyEntries } from './model.js';
6: import { COMPONENT_SOURCE } from './inspector-source.js';
7: import { componentTitle, formatComponentState } from './inspector-state.js';
8: import { renderFilesystems } from './fs-editor.js';
