70: // CHECKS: a trace run's stored hop denominators must be the run's FINAL hop
71: // count. An NX run's estimate (`host ? 9 : 8`) bakes `hop 1/9` before the
72: // answer proves the run ends at 2; once the final hop lands, relabelRun()
73: // rewrites every entry of that run so the log never advertises hops the
74: // run did not take (render() re-reads journeyEntries only).
75: export function relabelJourneyRun(run, totalHops) {
76:   journeyEntries = journeyEntries.map((entry) =>
77:     entry.run === run && entry.hop > 0
78:       ? { ...entry, label: `hop ${entry.hop}/${totalHops}` }
79:       : entry,
80:   );
81:   renderJourney();
82: }
