84: function renderJourney() {
85:   els.journeyLog.replaceChildren(
86:     ...journeyEntries.map((entry) => {
87:       const item = document.createElement('li');
88:       item.className = 'journey-entry';
89:       item.textContent = `${entry.label} · ${entry.text}`;
90:       return item;
91:     }),
92:   );
93: }
