101:   if (queue.length === 0) {
102:     const hint = document.createElement('span');
103:     hint.className = 'queue-empty-hint';
104:     hint.textContent = 'queue empty';
105:     container.replaceChildren(hint);
106:     return;
107:   }
108:   container.replaceChildren(
109:     ...queue.map((q) => {
110:       const pill = document.createElement('span');
111:       pill.className = `queue-pill${q.isYou ? ' you-pill' : ''}`;
112:       pill.textContent = `${q.from}: ${q.request}`;
113:       return pill;
114:     }),
