225:   const labels = describeSnapshot(snapshot);
226:   $('tick').textContent = labels.tick;
227:   $('queue-depth').textContent = labels.queueDepth;
228:   els.queueBar.style.width = labels.queueFill1;
229:   $('latency').textContent = labels.latency;
230:   $('served').textContent = labels.served;
