233:   els.servedRate.textContent = labels.servedRate;
234:   $('users-count').textContent = labels.users;
235:   $('server-address').textContent = labels.server1Address;
236:   els.serverIpChip.textContent = labels.server1Address;
237:   els.exchange.textContent = labels.exchangeSummary;
238:   els.hopStatus.textContent = labels.hopStatus;
239:   els.crowdCount.textContent = `${labels.users} browsers`;
240:   els.lastFrame.textContent = labels.networkLastFrame;
241:   const display = activeBrowserDisplay(snapshot, activeAddress);
242:   els.browserRoleName.textContent = browserName(activeAddress);
243:   els.browserIpChip.textContent = activeAddress;
244:   els.renderedBody.textContent = display
245:     ? display.body
246:     : 'Send a request or step a hop to render a response.';
