nextCompareSlots signature per brief: `nextCompareSlots(slots, newRun)` → `{ a, b, changed }`.

```js
// PINS: compare-tray slot allocation (b5) — pure; compare.js owns the DOM.
// Branch conditions: a run enters only with at least two hop entries (a
// crowd tick carries none and is rejected — the trace-runs-only rule); a
// run whose id matches a stored slot is a no-op; otherwise an empty A
// fills first, then B, and a third distinct run shifts A <- old B, B <- new.
export function nextCompareSlots(slots, newRun) {
  if (!newRun || !Array.isArray(newRun.entries) || newRun.entries.length < 2) {
    return { a: slots.a, b: slots.b, changed: false };
  }
  if (slots.a?.run === newRun.run || slots.b?.run === newRun.run) {
    return { a: slots.a, b: slots.b, changed: false };
  }
  if (!slots.a) return { a: newRun, b: slots.b, changed: true };
  if (!slots.b) return { a: slots.a, b: newRun, changed: true };
  return { a: slots.b, b: newRun, changed: true };
}
```

alignCompareRows:
```js
// PINS: compare alignment — rows align by hop index over max(hops); the
// exhausted side renders the em-dash; entry texts pass through verbatim
// (the tray never mints or rewrites hop frames — DL-1/DL-3).
export function alignCompareRows(left, right) {
  const rows = [];
  const total = Math.max(left.hops, right.hops);
  for (let n = 1; n <= total; n += 1) {
    rows.push({
      n,
      left: left.entries[n - 1]?.text ?? '—',
      right: right.entries[n - 1]?.text ?? '—',
    });
  }
  return rows;
}
```

